-- Estructuras adicionales para la ampliación de 65 RF.
-- Primero ejecutar 01_esquema.sql si no existe el esquema.
ALTER TABLE parcial_julian.usuarios ADD COLUMN IF NOT EXISTS identificacion VARCHAR(35);
ALTER TABLE parcial_julian.usuarios ADD COLUMN IF NOT EXISTS nivel VARCHAR(45);
ALTER TABLE parcial_julian.usuarios ADD COLUMN IF NOT EXISTS plan VARCHAR(40);
ALTER TABLE parcial_julian.usuarios ADD COLUMN IF NOT EXISTS creditos SMALLINT DEFAULT 0;
ALTER TABLE parcial_julian.usuarios ADD COLUMN IF NOT EXISTS metodologia BOOLEAN DEFAULT FALSE;
ALTER TABLE parcial_julian.usuarios ADD COLUMN IF NOT EXISTS telefono VARCHAR(30);
ALTER TABLE parcial_julian.ideas ADD COLUMN IF NOT EXISTS nivel VARCHAR(45);
ALTER TABLE parcial_julian.ideas ADD COLUMN IF NOT EXISTS modalidad VARCHAR(80);
ALTER TABLE parcial_julian.ideas ADD COLUMN IF NOT EXISTS desde DATE;
ALTER TABLE parcial_julian.ideas ADD COLUMN IF NOT EXISTS hasta DATE;
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS justificacion TEXT;
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS objetivos_especificos TEXT;
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS resultados_esperados TEXT;
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS modalidad VARCHAR(80) DEFAULT 'Desarrollo Tecnológico';
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS grupo_id BIGINT;
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS linea_id BIGINT;
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS periodo_id BIGINT;
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS version_actual INTEGER NOT NULL DEFAULT 1;
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS fecha_director TIMESTAMP;
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS fecha_evaluador TIMESTAMP;
ALTER TABLE parcial_julian.revisiones ADD COLUMN IF NOT EXISTS estado VARCHAR(20) NOT NULL DEFAULT 'EMITIDA';
CREATE TABLE IF NOT EXISTS parcial_julian.periodos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(90) UNIQUE NOT NULL, inicio DATE NOT NULL, fin DATE NOT NULL, apertura_ideas DATE, cierre_ideas DATE, estado VARCHAR(24) NOT NULL DEFAULT 'ABIERTO');
CREATE TABLE IF NOT EXISTS parcial_julian.grupos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(160) UNIQUE NOT NULL, activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS parcial_julian.lineas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, grupo_id BIGINT NOT NULL REFERENCES parcial_julian.grupos(id), nombre VARCHAR(180) NOT NULL, activo BOOLEAN DEFAULT TRUE, UNIQUE(grupo_id,nombre));
CREATE TABLE IF NOT EXISTS parcial_julian.integrantes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, anteproyecto_id BIGINT NOT NULL REFERENCES parcial_julian.anteproyectos(id), estudiante_id BIGINT NOT NULL REFERENCES parcial_julian.usuarios(id), UNIQUE(anteproyecto_id,estudiante_id));
CREATE TABLE IF NOT EXISTS parcial_julian.versiones (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, anteproyecto_id BIGINT NOT NULL REFERENCES parcial_julian.anteproyectos(id), version INTEGER NOT NULL, titulo VARCHAR(220), resumen TEXT, objetivos TEXT, justificacion TEXT, archivo_url VARCHAR(900), autor_id BIGINT REFERENCES parcial_julian.usuarios(id), fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(anteproyecto_id,version));
CREATE TABLE IF NOT EXISTS parcial_julian.documentos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, anteproyecto_id BIGINT NOT NULL REFERENCES parcial_julian.anteproyectos(id), tipo VARCHAR(90) NOT NULL, nombre VARCHAR(160) NOT NULL, url VARCHAR(900) NOT NULL, version INTEGER DEFAULT 1, usuario_id BIGINT REFERENCES parcial_julian.usuarios(id), fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parcial_julian.criterios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(170) UNIQUE NOT NULL, obligatorio BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS parcial_julian.notas_criterios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, anteproyecto_id BIGINT NOT NULL REFERENCES parcial_julian.anteproyectos(id), criterio_id BIGINT NOT NULL REFERENCES parcial_julian.criterios(id), evaluador_id BIGINT NOT NULL REFERENCES parcial_julian.usuarios(id), cumple BOOLEAN NOT NULL, observacion TEXT, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(anteproyecto_id,criterio_id,evaluador_id));
CREATE TABLE IF NOT EXISTS parcial_julian.decisiones (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, anteproyecto_id BIGINT NOT NULL REFERENCES parcial_julian.anteproyectos(id), coordinador_id BIGINT NOT NULL REFERENCES parcial_julian.usuarios(id), decision VARCHAR(30) NOT NULL, acta VARCHAR(90), fecha_acta DATE, observaciones TEXT, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parcial_julian.notificaciones (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario_id BIGINT NOT NULL REFERENCES parcial_julian.usuarios(id), anteproyecto_id BIGINT REFERENCES parcial_julian.anteproyectos(id), mensaje VARCHAR(500) NOT NULL, leida BOOLEAN DEFAULT FALSE, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parcial_julian.auditoria (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario_id BIGINT REFERENCES parcial_julian.usuarios(id), entidad VARCHAR(80) NOT NULL, entidad_id BIGINT, accion VARCHAR(100) NOT NULL, detalle TEXT, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_julian_notif ON parcial_julian.notificaciones(usuario_id,leida,fecha);
CREATE INDEX IF NOT EXISTS idx_julian_docs ON parcial_julian.documentos(anteproyecto_id,fecha);
CREATE INDEX IF NOT EXISTS idx_julian_audit ON parcial_julian.auditoria(fecha);

-- Etapas separadas: aprobación de anteproyecto y evaluación del proyecto final
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS etapa_actual VARCHAR(35) NOT NULL DEFAULT 'ANTEPROYECTO';
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS proyecto_final_url VARCHAR(900);
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS calificacion_final NUMERIC(3,2);
ALTER TABLE parcial_julian.anteproyectos ADD COLUMN IF NOT EXISTS version_final INTEGER NOT NULL DEFAULT 1;
ALTER TABLE parcial_julian.revisiones ADD COLUMN IF NOT EXISTS etapa VARCHAR(35) NOT NULL DEFAULT 'ANTEPROYECTO';
UPDATE parcial_julian.anteproyectos SET etapa_actual='ANTEPROYECTO_APROBADO' WHERE estado='APROBADO' AND etapa_actual='ANTEPROYECTO';
